def test_field_roundtrip(regs):
    regs.CTRL_REG.CTRL.write(0x3f)
    assert regs.CTRL_REG.CTRL.read() == 0x3f
    regs.CTRL_REG.CTRL.write(0)
    regs.CFG_REG.CFG.write(0x7ff)
    assert regs.CFG_REG.CFG.read() == 0x7ff
    regs.CFG_REG.CFG.write(0)
    regs.DMA_CFG_REG.DMA_CFG.write(0xffffff)
    assert regs.DMA_CFG_REG.DMA_CFG.read() == 0xffffff
    regs.DMA_CFG_REG.DMA_CFG.write(0)
    regs.AXI_DT1_REG.AXI_DT1.write(0xdeadbeef)
    assert regs.AXI_DT1_REG.AXI_DT1.read() == 0xdeadbeef
    regs.AXI_DT1_REG.AXI_DT1.write(0)
    regs.RESERVED_REG.RESERVED.write(0xdeadbeef)
    assert regs.RESERVED_REG.RESERVED.read() == 0xdeadbeef
    regs.RESERVED_REG.RESERVED.write(0)


def test_register_independence(regs):
    regs.CTRL_REG.CTRL.write(0x3f)
    regs.CFG_REG.CFG.write(0x7ff)
    regs.DMA_CFG_REG.DMA_CFG.write(0xffffff)
    regs.AXI_DT1_REG.AXI_DT1.write(0xabcd)
    regs.RESERVED_REG.RESERVED.write(0xabcd)
    assert regs.CTRL_REG.CTRL.read() == 0x3f
    assert regs.CFG_REG.CFG.read() == 0x7ff
    assert regs.DMA_CFG_REG.DMA_CFG.read() == 0xffffff
    assert regs.AXI_DT1_REG.AXI_DT1.read() == 0xabcd
    assert regs.RESERVED_REG.RESERVED.read() == 0xabcd
